-- Five more hikes and outings near the hut: Tschingelsee, Gehrihorn, Ramslauenen to Griesalp,
-- Gspaltenhornhütte and Sefinenfurgge. Facts with sources in docs/wanderungen-quellen-2.json, routes on the swisstopo trail network.
insert into hikes (slug, name, sort) values ('tschingelsee', 'Tschingelsee', 0) on conflict (slug) do nothing;
update hikes set
	category = 'wanderweg',
	sac = '',
	duration_min = 40,
	season_de = 'Das ganze Jahr',
	season_en = 'All year',
	start_name = 'Hüttli',
	end_name = 'Rastplatz Tschingel',
	transit_de = 'Zu Fuss ab dem Hüttli und auf dem gleichen Weg zurück.',
	transit_en = 'On foot from the hut and back the same way.',
	highlights_de = 'Schwemmebene mit mäandrierenden Bächen, entstanden nach einem Unwetter im Juli 1972
Wasservögel im Auengebiet
Ab Lengschwendi Blick ins hintere Kiental und auf die Gamchilücke',
	highlights_en = 'Floodplain with meandering streams, formed after a storm in July 1972
Water birds in the floodplain
From Lengschwendi a view into the upper Kiental and the Gamchilücke',
	tips_de = 'Der Tschingelsee ist ein Naturschutzgebiet und eine Aue von nationaler Bedeutung. Feuer nur am Rastplatz, Hunde an die Leine. Baden und ins Wasser waten ist verboten, das Ufer ist mit rot-schwarzen Pfosten gesperrt. Auch Zelten, Drohnen, Fischen und Pflanzen pflücken sind nicht erlaubt. Ob am Rastplatz Holz bereitliegt, ist nirgends angegeben, nimm am besten eigenes mit. Im Winter nur auf der signalisierten Schneeschuhroute.',
	tips_en = 'The Tschingelsee is a nature reserve and a floodplain of national importance. Fires only at the rest area, dogs on a lead. Bathing and wading are not allowed; the banks are closed off with red and black posts. Camping, drones, fishing and picking plants are also forbidden. No source says whether firewood is provided, so bring your own. In winter only on the marked snowshoe route.',
	family = true,
	loop = false,
	from_hut = true,
	alpine = false,
	de = 'Der kürzeste Ausflug ab dem Hüttli: über den Guggerwäg hinunter nach Bir Alperue und weiter zum ehemaligen Tschingelsee. Am Rastplatz beim Parkplatz am Nordwestrand gibt es Feuerstellen zum Bräteln.',
	en = 'The shortest outing from the hut: down the Guggerwäg to Bir Alperue and on to the former Tschingelsee. The rest area by the car park on the north-west edge has fireplaces for a barbecue.',
	url = 'https://www.naturschutzgebiete.sites.be.ch/de/start/schutzgebiete/tschingel.html',
	name = 'Tschingelsee',
	stops = '["Restaurant Alpenruh"]'::jsonb,
	waypoints = '[{"name":"Lengschwendi, Hüttli","elev":1184,"min":0,"distM":0},{"name":"Bir Alperue","elev":1141,"min":null,"distM":1611},{"name":"Rastplatz Tschingel","elev":1152,"min":40,"distM":2553}]'::jsonb,
